import{_ as o,o as r,c as a,a2 as d}from"./chunks/framework.DGvnA5EY.js";const s="/workbuddy-guide/assets/01-automation-alarm-clock.Depq5QF1.png",e="/workbuddy-guide/assets/02-official-automation-page.CdwfDmc9.png",i="/workbuddy-guide/assets/03-official-add-task.CFRG6yiq.png",n="/workbuddy-guide/assets/04-official-templates.DOoTECOY.png",l="/workbuddy-guide/assets/05-official-push-miniprogram.DyJMkT-T.png",p="/workbuddy-guide/assets/06-official-miniprogram-result.wV43mEPF.png",g="/workbuddy-guide/assets/07-official-wecom-bot-select.BeoLdkGv.png",u="/workbuddy-guide/assets/08-official-wecom-push.DiswqZDQ.png",y=JSON.parse('{"title":"第 10 章 自动化任务","description":"> 内容来源：WorkBuddy 官方指南 · 自动化（非官方整理，© 本指南作者，保留所有权利） 前九章的任务都需要你亲手点\\"发送\\"。这一章让 WorkBuddy 学会自己上闹钟：每天早上的 AI 新闻简报、每周五的工作周报、每月 1 号的数据整理——设定一次，到点自动执行，结果直接送到你手机上。","frontmatter":{"title":"第 10 章 自动化任务"},"headers":[],"relativePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 10 章 自动化任务/index.md","filePath":"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 10 章 自动化任务/index.md","lastUpdated":1791615980000}'),h={name:"bluebook/第一篇 使用手册：先把 WorkBuddy 用起来/第 10 章 自动化任务/index.md"};function m(c,t,b,k,q,_){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="第-10-章-自动化任务" tabindex="-1">第 10 章 自动化任务 <a class="header-anchor" href="#第-10-章-自动化任务" aria-label="Permalink to &quot;第 10 章 自动化任务&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南 · 自动化（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><p>前九章的任务都需要你亲手点&quot;发送&quot;。这一章让 WorkBuddy 学会<strong>自己上闹钟</strong>：每天早上的 AI 新闻简报、每周五的工作周报、每月 1 号的数据整理——设定一次，到点自动执行，结果直接送到你手机上。</p><p>这就是<strong>自动化</strong>：给 AI 配一个不会睡过头的闹钟。</p><h2 id="一、什么是自动化" tabindex="-1">一、什么是自动化 <a class="header-anchor" href="#一、什么是自动化" aria-label="Permalink to &quot;一、什么是自动化&quot;">​</a></h2><p>官方定义拆成人话：</p><ul><li>你在<strong>本地客户端</strong>保存一份定时任务配置（任务名、提示词、执行时间等）；</li><li>到了设定时间，WorkBuddy 会<strong>以你当前登录的身份</strong>自动发起一个 Agent 任务；</li><li>它按提示词执行查询、汇总、文件处理等工作，结果保存到指定目录；</li><li>任务只在配置的时间规则触发时执行，受频率、最大执行时长与并发控制限制。</li></ul><p><img src="'+s+'" alt="小黑坐在闹钟边，到点自动开工" loading="lazy"></p><p><em>配图为示意插画，用于帮助理解定时执行，与实际软件界面无关。</em></p><h2 id="二、打开自动化页面" tabindex="-1">二、打开自动化页面 <a class="header-anchor" href="#二、打开自动化页面" aria-label="Permalink to &quot;二、打开自动化页面&quot;">​</a></h2><p>左侧导航栏点**「自动化」<strong>。页面里可以查看已安排的任务和历史执行记录；底部是官方预置的</strong>自动化任务模板**。</p><p><img src="'+e+'" alt="左侧导航栏的「自动化」入口与添加按钮" loading="lazy"></p><p><em>此图片来自官方。</em></p><h2 id="三、创建第一个自动化任务" tabindex="-1">三、创建第一个自动化任务 <a class="header-anchor" href="#三、创建第一个自动化任务" aria-label="Permalink to &quot;三、创建第一个自动化任务&quot;">​</a></h2><p>点**「添加自动化」**，填写配置项：</p><table tabindex="0"><thead><tr><th>配置项</th><th>填什么</th><th>白话解释</th></tr></thead><tbody><tr><td><strong>名称</strong></td><td>比如「每日 AI 新闻推送」</td><td>给任务起个能认出来的名字</td></tr><tr><td><strong>提示词</strong></td><td>任务目标和输出要求</td><td>它到点后照着这段话干活</td></tr><tr><td><strong>工作空间</strong></td><td>默认自动分配 automation-xxxx</td><td>任务在哪个目录干活、文件存哪</td></tr><tr><td><strong>权限模式</strong></td><td>默认权限 / 完全访问权限</td><td>控制它执行时能动多少东西</td></tr><tr><td><strong>模型和技能</strong></td><td>指定模型、技能、专家、连接器</td><td>干活用哪套班子</td></tr><tr><td><strong>定时规则</strong></td><td>执行频率 + 生效日期区间</td><td>什么时候跑</td></tr><tr><td><strong>推送到小程序/企微</strong></td><td>开关</td><td>结果要不要送到手机</td></tr></tbody></table><p><img src="'+i+'" alt="添加自动化任务弹窗：名称、提示词、执行频率、推送开关" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>权限模式怎么选</strong>：默认权限更安全，日常汇总、写报告够用；只有确认任务必须读写更大范围（比如整理整盘文件）时，才用完全访问权限——毕竟它是无人值守在跑。</p><h2 id="四、不想写提示词-从模板开始" tabindex="-1">四、不想写提示词？从模板开始 <a class="header-anchor" href="#四、不想写提示词-从模板开始" aria-label="Permalink to &quot;四、不想写提示词？从模板开始&quot;">​</a></h2><p>自动化页面下方有官方模板：每日 AI 新闻推送、每周工作周报、体检预约提醒、每日英语单词、会议前准备……点开就能用，按需改。</p><p><img src="'+n+'" alt="自动化任务模板：覆盖新闻、周报、提醒等场景" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>推荐第一次就从「每日 AI 新闻推送」改起：模板的提示词已经写好&quot;筛选 3–5 条有价值的信息&quot;，你只需要换成自己关心的领域。</p><h2 id="五、定时规则怎么设" tabindex="-1">五、定时规则怎么设 <a class="header-anchor" href="#五、定时规则怎么设" aria-label="Permalink to &quot;五、定时规则怎么设&quot;">​</a></h2><p>这里有个官方专门强调的点：</p><ul><li>支持<strong>每周多天</strong>：比如&quot;每周一、三、五 09:00&quot;——<strong>一条规则就能表达</strong>；</li><li>支持<strong>每月多天</strong>：比如&quot;每月 1 日、15 日、28 日 09:00&quot;；</li><li>同一任务的多个执行日期，请<strong>合并在一条规则</strong>里，<strong>不要拆成多个自动化任务</strong>。</li></ul><p>为什么？拆成三个任务就是三份配置、三次触发记录，改一次提示词要改三处。一条规则，改一处就够。</p><p>「有效期」也不难懂：想让任务只跑某段时间（比如整个项目周期），设起止日期；不设就是长期有效。</p><h2 id="六、让结果主动来找你-推送到小程序和企业微信" tabindex="-1">六、让结果主动来找你：推送到小程序和企业微信 <a class="header-anchor" href="#六、让结果主动来找你-推送到小程序和企业微信" aria-label="Permalink to &quot;六、让结果主动来找你：推送到小程序和企业微信&quot;">​</a></h2><p>任务跑完了，人可能不在电脑前。两个推送开关就是干这个的。</p><p><strong>推送到 WorkBuddy 微信小程序</strong>：打开开关（在添加任务弹窗底部），任务完成后结果自动发进小程序，手机上直接看。</p><p><img src="'+l+'" alt="打开「推送到 WorkBuddy 微信小程序」开关" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><img src="'+p+'" alt="在小程序里查看自动化任务结果" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><strong>推送到企业微信 bot</strong>：打开「推送到企业微信 bot」开关后会弹出选择，两种来源二选一：</p><table tabindex="0"><thead><tr><th>来源</th><th>说明</th><th>适合</th></tr></thead><tbody><tr><td>助理的企业微信 bot</td><td>复用第 8 章「企微助理集成」的通道</td><td>已绑定企微助理的用户</td></tr><tr><td>独立的自动化通知 bot</td><td>单独注册，与助理消息互不影响</td><td>只想收通知的场景</td></tr></tbody></table><p><img src="'+g+'" alt="选择通知机器人：两种来源二选一" loading="lazy"></p><p><em>此图片来自官方。</em></p><p><img src="'+u+'" alt="开启「推送到企业微信 bot」并选择来源" loading="lazy"></p><p><em>此图片来自官方。</em></p><p>三个细节值得记住：</p><ul><li>绑定助理 bot 时建议用 <strong>WebSocket 长连接</strong>——URL 回调有时效性风险，长时间不触发可能失效（界面会以 ⚠ 提醒）；</li><li>通道解绑时，推送开关<strong>不会</strong>自动关闭，界面上会出现红点提示重新绑定；</li><li>用助理 bot 推送的结果<strong>只作通知</strong>，不会写进助理的对话上下文——它不会&quot;记得&quot;这次任务。</li></ul><h2 id="七、安全提醒-它在你睡觉时也在干活" tabindex="-1">七、安全提醒：它在你睡觉时也在干活 <a class="header-anchor" href="#七、安全提醒-它在你睡觉时也在干活" aria-label="Permalink to &quot;七、安全提醒：它在你睡觉时也在干活&quot;">​</a></h2><p>自动化是全书里唯一<strong>无人值守</strong>运行的功能，官方的提醒原样搬给你：</p><ul><li><strong>审慎设置涉及文件写入、删除、资金操作的提示词</strong>——不确定的指令，别让它定时跑；</li><li>新任务先<strong>用低频率试运行</strong>，确认理解没问题再放大频率；</li><li>对涉及文件改动、数据变更、对外发送的结果，<strong>保留可追溯的日志</strong>；</li><li>积分消耗视任务复杂度：简单提醒很低，代码巡检、文档汇总这类可能消耗较多。</li></ul><h2 id="本章任务清单" tabindex="-1">本章任务清单 <a class="header-anchor" href="#本章任务清单" aria-label="Permalink to &quot;本章任务清单&quot;">​</a></h2><ul><li>[ ] 打开左侧「自动化」页面，浏览一遍任务模板</li><li>[ ] 从模板创建你的第一个自动化任务（建议「每日 AI 新闻推送」）</li><li>[ ] 设置一条&quot;每周多天&quot;的定时规则，注意合并在一条规则里</li><li>[ ] 打开「推送到 WorkBuddy 微信小程序」，手机上收到第一次结果</li><li>[ ] （可选）为任务设置到期日期，学会用「有效期」控制任务寿命</li></ul><h2 id="小白说明书" tabindex="-1">小白说明书 <a class="header-anchor" href="#小白说明书" aria-label="Permalink to &quot;小白说明书&quot;">​</a></h2><blockquote><p><strong>自动化</strong>：到点自动执行任务的定时功能。配置一次，按规则反复跑。</p><p><strong>触发</strong>：到了设定时间，任务自动开始执行的那一刻。</p><p><strong>权限模式</strong>：限制无人值守任务能&quot;动&quot;多少东西的开关。默认权限更安全。</p><p><strong>工作空间</strong>：任务执行时所在的文件夹。自动化默认分配 automation-xxxx 目录。</p><p><strong>生效日期区间</strong>：任务只在起止日期内运行，过期自动不跑。</p><p><strong>推送</strong>：任务完成后把结果发到小程序或企业微信，不用守在电脑前。</p><p><strong>无人值守</strong>：没有人盯着、自动运行的状态。所以涉及删文件、花钱的提示词要格外谨慎。</p></blockquote><hr><p><em>下一篇：课外阅读——一章看懂 AI 工作系统，把前十章串成完整拼图。</em></p><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>',54)])])}const x=o(h,[["render",m]]);export{y as __pageData,x as default};
